import json, os, glob, sys, collections
D='/root/.claude/projects/-home-user-fortress/fe616d40-a9c6-56d7-9da1-7168a172765d/subagents/workflows'
runs={'p-run1':'wf_deae5f0c-1d9','c-run1':'wf_727d9847-e38','c-run2':'wf_ddb6159d-7ff','c-run3':'wf_372cca35-338','c-run4':'wf_af67b86b-89c','reconcile':'wf_bb9edd49-b79'}
def scan(f):
    seen={}; ts=[]
    for line in open(f, errors='replace'):
        try: r=json.loads(line)
        except Exception: continue
        t=r.get('timestamp')
        if t: ts.append(t)
        m=r.get('message') if isinstance(r.get('message'),dict) else None
        if not m or 'usage' not in m: continue
        seen[m.get('id') or id(m)]=m['usage']
    w=sum(u.get('input_tokens',0)+u.get('cache_creation_input_tokens',0) for u in seen.values())
    return w,len(seen),(min(ts) if ts else ''),(max(ts) if ts else '')
out=[]
for n,r in runs.items():
    J=[json.loads(l) for l in open(f'{D}/{r}/journal.jsonl')]
    resagents={d['agentId'] for d in J if d['type']=='result'}
    for f in sorted(glob.glob(f'{D}/{r}/agent-*.jsonl')):
        aid=os.path.basename(f)[6:-6]
        meta=json.load(open(f[:-6]+'.meta.json'))
        w,c,t0,t1=scan(f)
        out.append(dict(run=n,agent=aid,label=meta.get('description'),phase=meta.get('workflowPhase'),model=meta.get('model'),w=w,calls=c,t0=t0,t1=t1,result=aid in resagents))
json.dump(out,open(sys.argv[1],'w'),indent=0)
print(len(out))
EOF
