    m=re.search(r'(\d+)\s+(?:rows\s+)?pass(?:ed|es)?\b[^.\n]*?(\d+)\s+(?:rows\s+)?fail',head,re.I)
    if m: return int(m.group(1)),int(m.group(2))
    m=re.search(r'pass(?:ed)?:?\s+(\d+)[^\n]*?fail(?:ed|s)?:?\s+(\d+)',head,re.I)
